export async function request(config,body){if(!config.endpoint||!config.key)throw Error('Primero conecta tu archivo en Conexión y respaldos.');if(!/^https:\/\/script\.google\.com\/macros\/s\/[\w-]+\/exec$/.test(config.endpoint))throw Error('El enlace de conexión debe ser una aplicación web de Google Apps Script.');const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),55000);try{const r=await fetch(config.endpoint,{method:'POST',redirect:'follow',credentials:'omit',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({...body,key:config.key}),signal:controller.signal});if(!r.ok)throw Error('No se pudo contactar con Google. Tus cambios siguen guardados en el teléfono.');const json=await r.json();if(!json.ok)throw Error(json.error||'Google no pudo completar la sincronización.');return json;}catch(e){if(e.name==='AbortError')throw Error('Google tardó demasiado. Puedes volver a sincronizar; tus cambios siguen guardados.');if(e instanceof TypeError)throw Error('No se pudo conectar. Revisa internet y que el enlace esté publicado para permitir la conexión.');throw e;}finally{clearTimeout(timer);}}
export async function enablePush(config){if(!('serviceWorker'in navigator)||!('PushManager'in window)||!('Notification'in window))throw Error('Instala la app en la pantalla de inicio y ábrela desde su icono para activar avisos.');if(!config.vapidPublicKey)throw Error('El barrido automático todavía necesita activar las notificaciones en la conexión.');const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('No se autorizó el permiso de notificaciones.');const sw=await navigator.serviceWorker.ready;const padding='='.repeat((4-config.vapidPublicKey.length%4)%4);const raw=atob((config.vapidPublicKey+padding).replace(/-/g,'+').replace(/_/g,'/'));const key=Uint8Array.from(raw,x=>x.charCodeAt(0));const subscription=await sw.pushManager.getSubscription()||await sw.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key});await request(config,{action:'subscribe',subscription:subscription.toJSON()});return true;}
